## This is the original html creation function for use with the gradescope
## implementation.
def make_html_for_problem(prob, problem_set="not in a set", filename=None):

    if filename == None:
        filename = prob["title"].title().replace(' ','') + ".p9"

    html = HTML_TEMPLATE
    html = html.replace("__TITLE__", prob["title"])
    html = html.replace( "__PROBLEM_SET__", problem_set )
    html = html.replace( "__ATTRIBUTION__", prob["attribution"])

    if "outline" in prob.keys():
      html = html.replace( "__OUTLINE__","<p><b>Outline: </b>" + prob["outline"])
    else:
      html = html.replace( "__OUTLINE__", "")

    html = html.replace( "__LOGIC__", prob["logic"] )
    html = html.replace( "__P9FILE__", filename )
    html = html.replace( "__MARKS__", str(len(prob["English"])*2) )
    problem = "<table cellpadding=6>"
    for i, ass in enumerate(prob["English"][:-1]):
        problem += "<tr bgcolor=#DDFFDD><td align=right><b>A{}</b></td> <td>{}</td></tr>\n".format(i+1,ass)
    problem += "<tr bgcolor=#DDFFFF><td align=right><b>Goal</b></td> <td>{}</td></tr>\n".format(prob["English"][-1])
    problem += "</table>"

    html = html.replace( "__PROBLEM__", problem )
    vocspec = ""
    for voctype in prob["vocabulary"]:
        voclist = prob["vocabulary"][voctype]
        tt_voclist = ["<font size=\"+1\"><tt>"+v+"</tt></font>" for v in voclist]
        vocstr = ", ".join(tt_voclist)
        vocspec += "<b>{}:</b> {}<p>".format(voctype, vocstr)

    html = html.replace( "__VOCABULARY__", vocspec )

    if "notes" in prob:
        html += "<h4>Notes:</h4>\n<ul>\n"
        for n in prob["notes"]:
            html += "<li>" + n + "</li>\n"
        html += "</ul>"

    html += HTML_END_BODY
    return html

