PROBLEM_SETS = {
    "propositional": PROPOSITIONAL_PROBLEMS,
    "first_order_intro": FIRST_ORDER_INTRO_PROBLEMS,
    "challenging": CHALLENGING_PROBLEMS,
}

def get_problem(problem_set, problem_name):
    if problem_set not in PROBLEM_SETS:
        raise ValueError(f"Unrecognised problem set: {problem_set}")
    problems = PROBLEM_SETS[problem_set]
    if problem_name not in problems:
        raise ValueError(
            f"Problem {problem_name} not found in problem set {problem_set}")
    return problems[problem_name]

def problem_html( problem ):
    html = HTML_HEAD + HTML_TOP
    html = html.replace("__TITLE__", problem["title"])
    #html = html.replace( "__PROBLEM_SET__", problem_set )
    html = html.replace( "__PROBLEM_SET__", "" )
    html = html.replace( "__ATTRIBUTION__", problem["attribution"])
    html = html.replace( "__LOGIC__", problem["logic"] )

    if "outline" in problem.keys():
      html = html.replace( "__OUTLINE__","<p><b>Outline: </b>" + problem["outline"])
    else:
      html = html.replace( "__OUTLINE__", "")

    html +=  "\n<table cellpadding=6>"
    for i, ass in enumerate(problem["English"][:-1]):
        html += f"<tr bgcolor=#DDFFDD><td align=right><b>A{i+1}</b></td> <td>{ass}</td></tr>\n"
    goal = problem["English"][-1]
    html += f"<tr bgcolor=#DDFFFF><td align=right><b>Goal</b></td> <td>{goal}</td></tr>\n"
    html += "</table>"
    html += HTML_END_BODY
    return html

def display_problem_html(problem_set, problem_name):
    from IPython.display import HTML, display
    html = problem_html(get_problem(problem_set, problem_name))
    display(HTML(html))

